import { Entity } from "../../Engine/Entity";

/**
 * 经营场景建筑实体，继承项目原生Entity，不新增组件体系
 * kind = 'building'，复用Engine统一生命周期、数字ID、World/ViewRegistry
 */
export class BuildingEntity extends Entity {
    public readonly kind = 'building';

    // 建筑业务字段
    public typeId: string;
    public pendingIncome: number = 0;
    public synergyMultiplier: number = 1.0;
    public level: number = 1;

    constructor(gridX: number, gridY: number, typeId: string) {
        super();
        // 直接复用基类自带 x/y 存格子坐标，不再额外写 gridX gridY
        this.x = gridX;
        this.y = gridY;
        this.typeId = typeId;
    }
}
